"use client";

import React, { InputHTMLAttributes, ReactNode } from "react";

import { Field } from "./Field";
import { useStableId } from "../hooks/useStableId";
import styles from "./Input.module.css";

export interface InputProps
  extends Omit<InputHTMLAttributes<HTMLInputElement>, "helperText"> {
  label?: string;
  labelStyle?: "plain" | "notch";
  variant?: "default" | "long" | "full";
  helperText?: string;
  /** Field-level error message; sets aria-invalid and joins aria-describedby. */
  error?: string;
  icon?: ReactNode;
}

export function Input({
  label,
  labelStyle = "plain",
  variant = "default",
  className = "",
  id,
  disabled,
  readOnly,
  helperText,
  error,
  icon,
  "aria-describedby": ariaDescribedBy,
  "aria-invalid": ariaInvalid,
  ...props
}: InputProps) {
  const inputId = useStableId("input", id);

  return (
    <Field
      id={inputId}
      label={label}
      labelStyle={labelStyle}
      helperText={helperText}
      error={error}
      describedBy={ariaDescribedBy}
      invalid={ariaInvalid}
      className={className}
      style={
        {
          "--field-width":
            variant === "full"
              ? "100%"
              : variant === "long"
                ? "360px"
                : "240px",
        } as React.CSSProperties
      }
    >
      {(attributes) => (
        <>
          <div className={icon ? styles.withIcon : undefined}>
            {icon ? <div className={styles.icon}>{icon}</div> : null}
            <input
              id={inputId}
              className={styles.input}
              disabled={disabled}
              readOnly={readOnly}
              {...props}
              {...attributes}
            />
          </div>
        </>
      )}
    </Field>
  );
}

.input {
  display: block;
  width: 100%;
  min-height: 44px;
  box-sizing: border-box;
  border: 0;
  outline: none;
  background: transparent;
  color: var(--text-primary);
  font: 1rem/1.4 var(--font-mono);
  padding: 12px;
}
.input:disabled {
  cursor: not-allowed;
}
.icon {
  position: absolute;
  right: 12px;
  top: 50%;
  transform: translateY(-50%);
  display: flex;
  color: var(--text-secondary);
  pointer-events: none;
}
.withIcon .input {
  padding-right: 44px;
}
